<?php /* Avisos del sistema y reintento autorizado de envíos (CU28). */ ?>
<div class="page-heading"><div><span class="eyebrow">COMUNICACIÓN</span><h1>Avisos del sistema</h1><p>Consulta tus avisos y el estado de sus envíos por Telegram.</p></div></div>
<?php require BASE_PATH.'/views/_appointment_errors.php'; ?>
<section class="card"><form class="availability-search" method="get"><label>Estado<select name="estado"><?php foreach (['todos'=>'Todos','pendiente'=>'Pendiente','enviado'=>'Enviado','error'=>'Error','omitido'=>'Sin envío'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $state===$value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="button secondary" type="submit">Consultar avisos</button></form></section>
<section class="card"><div class="notice-list">
<?php foreach ($listing['items'] as $row): ?><article class="notice-item"><h2><?= e(App\NoticeService::SUBJECTS[$row['tipo']] ?? 'Aviso del sistema') ?></h2><p class="field-help"><?= e(clinic_datetime($row['creado_en'])) ?><?php if ($user['rol']!=='paciente'): ?> · <?= e($row['paciente']) ?><?php endif; ?> · <?= e(['pendiente'=>'Pendiente','enviado'=>'Enviado','error'=>'Error','omitido'=>'Sin envío'][$row['estado']]) ?></p><p><?= e($row['texto']) ?></p>
<?php if ($row['estado']==='enviado'): ?><p class="field-help">Telegram aceptó el envío el <?= e(clinic_datetime($row['enviado_en'])) ?>. Esto no confirma la lectura ni la asistencia.</p><?php elseif (!$row['vinculado']): ?><p class="field-help">Telegram sin vincular. El aviso está disponible aquí.</p><?php endif; ?>
<?php if ($row['ultimo_error']): ?><p class="field-help"><?= e($row['ultimo_error']) ?></p><?php endif; ?>
<?php if ($row['cita_visible'] && App\AppointmentService::canView($user)): ?><p><a href="/citas/<?= (int) $row['cita_visible'] ?>">Ver cita <?= e(App\AppointmentService::code((int) $row['cita_visible'])) ?></a></p><?php endif; ?>
<?php if ($row['estado']==='error' && $user['rol']!=='paciente' && (int) $row['intentos']<10): ?><form class="form-stack" method="post" action="/avisos/<?= (int) $row['id'] ?>/reintentar"><?= csrf_field() ?><input type="hidden" name="version" value="<?= e(App\NoticeService::version($row)) ?>"><label class="catalog-check"><input type="checkbox" name="reintento_autorizado" value="1" required> Revisé el envío y autorizo reintentarlo; podría recibirse nuevamente.</label><button class="button secondary" type="submit">Autorizar reintento</button></form><?php endif; ?></article><?php endforeach; ?>
<?php if (!$listing['items']): ?><p class="empty">No hay avisos con estos filtros.</p><?php endif; ?></div><?php require BASE_PATH.'/views/_appointment_pagination.php'; ?></section>
